import java.util.*;
import java.io.*;

public class Main {
    private static final int MAXN = 202;
    private static final int INF = 0x3f3f3f3f;
    private static int[][] flow = new int[MAXN][MAXN];
    private static int[][] capacity = new int[MAXN][MAXN];
    private static int[] parent = new int[MAXN];
    private static int[] dist = new int[MAXN];
    private static int[][] gridA = new int[11][11];
    private static int[][] gridB = new int[11][11];
    private static int n, t, bi, bj;
    private static int[][] matrix = new int[101][101];
    private static List<Integer> listA = new ArrayList<>();
    private static List<Integer> listB = new ArrayList<>();
    private static List<Integer> listC = new ArrayList<>();
    private static final int[][] directions = {{0,1},{0,-1},{1,0},{-1,0}};
    private static final int INF_PLUS_ONE = INF + 1;

    private static int edmonds_karp(int nNodes, int s, int e) {
        int total = 0;
        while (true) {
            Arrays.fill(parent, -1);
            dist[s] = INF;
            Queue<Integer> q = new LinkedList<>();
            q.offer(s);
            while (!q.isEmpty() && parent[e] < 0) {
                int u = q.poll();
                for (int v = 0; v < nNodes; v++) {
                    if (parent[v] < 0 && capacity[u][v] - flow[u][v] > 0) {
                        parent[v] = u;
                        dist[v] = Math.min(dist[u], capacity[u][v] - flow[u][v]);
                        q.offer(v);
                    }
                }
            }
            if (parent[e] < 0) break;
            for (int v = e; v != s; v = parent[v]) {
                flow[parent[v]][v] += dist[e];
                flow[v][parent[v]] -= dist[e];
            }
            total += dist[e];
        }
        return total;
    }

    private static void explore(int A, int B, int[] visited, boolean check) {
        Queue<int[]> q = new LinkedList<>();
        int size = n * n;
        visited[A * n + B] = 0;
        q.offer(new int[]{A, B});
        while (!q.isEmpty()) {
            int[] p = q.poll();
            int pIdx = p[0]*n + p[1];
            int dis = visited[pIdx];
            if (check && (matrix[bi * n + bj][pIdx] <= dis || t <= dis)) {
                if (matrix[bi * n + bj][pIdx] < dis || t < dis) visited[pIdx] = INF_PLUS_ONE;
                continue;
            }
            for (int d = 0; d < 4; d++) {
                int ni = p[0] + directions[d][0];
                int nj = p[1] + directions[d][1];
                if (ni < 0 || nj < 0 || ni >= n || nj >= n) continue;
                if (gridB[ni][nj] < '0' || gridB[ni][nj] > '9') continue;
                int qIdx = ni * n + nj;
                if (visited[qIdx] != INF_PLUS_ONE) continue;
                visited[qIdx] = dis + 1;
                q.offer(new int[]{ni, nj});
            }
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        n = Integer.parseInt(st.nextToken());
        t = Integer.parseInt(st.nextToken());
        for (int i = 0; i < n; i++) {
            st = new StringTokenizer(br.readLine());
            for (int j = 0; j < n; j++) {
                gridA[i][j] = st.nextToken().charAt(0);
            }
        }
        for (int i = 0; i < n; i++) {
            st = new StringTokenizer(br.readLine());
            for (int j = 0; j < n; j++) {
                gridB[i][j] = st.nextToken().charAt(0);
            }
        }
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (gridA[i][j] == 'Z') {
                    bi = i;
                    bj = j;
                }
            }
        }
        for (int[] row : matrix) Arrays.fill(row, INF);
        int[] visited = new int[n * n];
        Arrays.fill(visited, -1);
        explore(bi, bj, visited, false);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (gridA[i][j] >= '1' && gridA[i][j] <= '9') {
                    int[] v2 = new int[n * n];
                    Arrays.fill(v2, -1);
                    explore(i, j, v2, true);
                    // copy results
                    for (int idx = 0; idx < n * n; idx++) {
                        matrix[i * n + j][idx] = v2[idx];
                    }
                }
            }
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (gridA[i][j] >= '0' && gridA[i][j] <= '9') {
                    int p = i * n + j;
                    capacity[p + 2 + n * n][1] = gridA[i][j] - '0';
                }
            }
        }

        int z = bi * n + bj;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (gridB[i][j] >= '0' && gridB[i][j] <= '9') {
                    int p = i * n + j;
                    capacity[0][p + 2] = gridB[i][j] - '0';
                    for (int k = 0; k < listA.size(); k++) {
                        int ii = listA.get(k);
                        int jj = listB.get(k);
                        int qIdx = ii * n + jj;
                        if (matrix[p][qIdx] < INF)
                            capacity[p + 2][qIdx + 2 + n * n] = INF;
                    }
                }
            }
        }
        System.out.println(edmonds_karp(2 + n * n, 0, 1));
    }
}
